<?php require_once __DIR__ . '/includes/db.php'; require_once __DIR__ . '/includes/functions.php';
$pdo=db();
$meetings=$pdo->query("SELECT * FROM meetings WHERE status='scheduled' AND starts_at >= NOW() ORDER BY starts_at ASC LIMIT 3")->fetchAll();
$stories=$pdo->query("SELECT * FROM stories WHERE status='published' ORDER BY published_at DESC LIMIT 3")->fetchAll();
$galleries=$pdo->query("SELECT g.*, (SELECT gi.file_path FROM gallery_images gi WHERE gi.gallery_id=g.id ORDER BY gi.sort_order, gi.id LIMIT 1) AS preview_image FROM galleries g WHERE g.status='published' ORDER BY g.created_at DESC LIMIT 3")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>taosarts.org</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="museum-body"><header class="site-header"><a class="brand-lockup" href="index.php"><div class="logo-mark" aria-hidden="true"></div><div><div class="logo"><span>taos</span>arts.org</div><p class="brand-tag">Create. Connect. Critique.</p></div></a><nav class="nav"><a href="index.php">Home</a><a href="#meetings">Meetings</a><a href="questionnaire.php?slug=community-survey">Survey</a><a href="#stories">Stories</a><a href="#galleries">Galleries</a></nav></header><main><section class="hero hero-illustrated"><div class="hero-copy"><p class="eyebrow">Weekly Artist Gathering</p><h1>Taos Critique Club</h1><p class="hero-lead">A welcoming, high-desert space for artists to share work, receive thoughtful feedback, and grow in company.</p><p>A welcoming space for artists of all kinds to share their work, give and receive thoughtful feedback, and grow together. Two stars and what you want to see. Tea, cookies, and good conversation every time.</p><div class="hero-actions"><a class="btn" href="questionnaire.php?slug=community-survey">Take the survey</a> <a class="btn alt" href="#meetings">Next meetings</a></div><dl class="hero-facts"><div><dt>When</dt><dd>Sundays, noon to 3 pm</dd></div><div><dt>Where</dt><dd>Taos, New Mexico</dd></div><div><dt>Atmosphere</dt><dd>Warm, rigorous, generous</dd></div></dl></div><div class="hero-image-frame"><img src="assets/img/site/hero-doorway.png" alt="Adobe doorway opening toward a Taos landscape with pottery and desert plants."></div></section><section class="section icon-grid"><div class="icon-card"><span class="symbol">01</span><h3>Collaborative</h3><p>We gather to help each other see the work more clearly and speak about it more precisely.</p></div><div class="icon-card"><span class="symbol">02</span><h3>Supportive</h3><p>Critique stays kind, useful, and welcoming to new voices without losing rigor.</p></div><div class="icon-card"><span class="symbol">03</span><h3>Tea and cookies</h3><p>Nourishment and conversation matter as much as technique, process, and craft.</p></div><div class="icon-card"><span class="symbol">04</span><h3>Rooted in Taos</h3><p>Shaped by this land, its artists, and the people who call it home.</p></div></section><section class="section feature-split"><div class="feature-copy"><p class="eyebrow">About the Club</p><h2>What is the Critique Club?</h2><p>We are building a weekly artist gathering where people can share work in progress, talk through questions, and practice giving feedback that is specific, respectful, and energizing.</p><p>Each artist receives two stars, one suggestion, and the rare benefit of being seen by people who care about the work becoming more itself.</p><p><a class="text-link" href="#meetings">See upcoming meetings</a></p></div><div class="feature-image"><img src="assets/img/site/critique-circle.png" alt="A small group of artists in a Taos studio critique circle with artwork, tea, and cookies."></div></section><section class="section meeting-shell" id="meetings"><div class="section-heading"><div><p class="eyebrow">Program Calendar</p><h2>Upcoming meetings</h2><p>Plan ahead for the next few critique club gatherings, including location changes, featured snacks, and special mini-presentations.</p></div><a class="btn alt" href="questionnaire.php?slug=community-survey">Share what you'd like to cover</a></div><div class="meeting-grid"><?php foreach($meetings as $meeting): ?><article class="meeting-card museum-card"><div class="meeting-topline"><p class="eyebrow"><?=h(format_meeting_datetime($meeting['starts_at']))?></p><?php if($meeting['ends_at']): ?><p class="meeting-end">Ends <?=h(date('g:i a', strtotime($meeting['ends_at'])))?></p><?php endif; ?></div><h3><?=h($meeting['title'])?></h3><ul class="meeting-details"><?php if($meeting['location_name']): ?><li><span>Where</span><div><?=h($meeting['location_name'])?><?php if($meeting['location_details']): ?><small><?=h($meeting['location_details'])?></small><?php endif; ?></div></li><?php endif; ?><?php if($meeting['focus_topic']): ?><li><span>Focus</span><div><?=h($meeting['focus_topic'])?></div></li><?php endif; ?><?php if($meeting['featured_snack']): ?><li><span>Snack</span><div><?=h($meeting['featured_snack'])?></div></li><?php endif; ?><?php if($meeting['presenter_name'] || $meeting['presenter_topic']): ?><li><span>Presenter</span><div><?=h(trim(($meeting['presenter_name'] ? $meeting['presenter_name'] : '') . ($meeting['presenter_topic'] ? ' on ' . $meeting['presenter_topic'] : '')))?></div></li><?php endif; ?></ul><?php if($meeting['special_note']): ?><p class="meeting-note"><?=nl2br(h($meeting['special_note']))?></p><?php endif; ?></article><?php endforeach; ?></div></section><section class="section civic-split" id="newsletter"><div class="survey-panel museum-card"><p class="eyebrow">Community Input</p><h2>Help shape our creative community</h2><p>The first step is a community questionnaire. Share what you want to discuss, what kind of artist you are, and how you may want to contribute. Your input helps shape the rhythm, subject matter, and future programs of the club.</p><a class="btn" href="questionnaire.php?slug=community-survey">Take the survey</a><p class="quiet-note">Your voice helps shape the direction of the club.</p></div><form class="card newsletter-card museum-card" method="post" action="newsletter_signup.php"><p class="eyebrow">Newsletter</p><h2>Stay in the loop</h2><p>Get updates on Critique Club, artist stories, resources, and opportunities for artists in Taos.</p><div class="form-row"><label>Email address</label><input name="email" type="email" required placeholder="you@example.com"></div><button class="btn">Subscribe</button></form></section><section class="section collection-section" id="stories"><div class="section-heading"><div><p class="eyebrow">Artist Stories</p><h2>Recent stories</h2><p>Artist profiles, process notes, and reflections from the Taos creative community.</p></div></div><div class="collection-grid"><?php foreach($stories as $s): ?><article class="collection-card museum-card"><?php if($s['featured_image']): ?><img class="card-media" src="<?=h($s['featured_image'])?>" alt="<?=h($s['title'])?>"><?php endif; ?><div class="collection-copy"><h3><?=h($s['title'])?></h3><p><?=h($s['excerpt'])?></p><a class="text-link" href="story.php?slug=<?=h($s['slug'])?>">Read story</a></div></article><?php endforeach; ?></div></section><section class="section collection-section" id="galleries"><div class="section-heading"><div><p class="eyebrow">Gallery Rooms</p><h2>Galleries</h2><p>Collections, curated rooms, and visual highlights from local makers and spaces.</p></div></div><div class="collection-grid"><?php foreach($galleries as $g): ?><article class="collection-card museum-card"><?php if($g['preview_image']): ?><img class="card-media" src="<?=h($g['preview_image'])?>" alt="<?=h($g['title'])?>"><?php endif; ?><div class="collection-copy"><h3><?=h($g['title'])?></h3><p><?=h($g['description'])?></p><a class="text-link" href="gallery.php?slug=<?=h($g['slug'])?>">View gallery</a></div></article><?php endforeach; ?></div></section></main><footer class="footer"><div><div class="footer-brand">taosarts.org</div><p>Building a creative community rooted in Taos, New Mexico.</p></div><div><b>Join us Sundays</b><p>Noon to 3 pm<br>Tea, cookies, conversation, and community.</p></div><div><b>Questions?</b><p>info@taosarts.org</p></div></footer></body></html>
